INSERT INTO agent_messages VALUES(21,'test_langfuse_session','{"arguments": "{\"input\":\"Billing codes for virtual care in Ontario\"}", "call_id": "call_tOMhO7FUdHLixUQbPQQDJBQK", "name": "dr_off", "type": "function_call", "id": "fc_68d96e6ece488190ba0f34e339d5a90605ba4b77ac14e6cc", "status": "completed"}','2025-09-28 17:21:02');
INSERT INTO agent_messages VALUES(22,'test_langfuse_session','{"call_id": "call_BOIS4w0fIyQ3hMgsV5MvD10h", "output": "### Direct Answer\nThe **CPSO** has established several guidelines regarding virtual care, which outline mandatory expectations for physicians. Key documents include:\n\n1. **[Virtual Care](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Virtual-Care)** - This policy emphasizes the necessity for comprehensive care delivery, even in virtual settings.\n   \n2. **[Advice to the Profession: Virtual Care](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Virtual-Care/Advice-to-the-Profession-Virtual-Care)** - This document offers guidance on best practices, ensuring quality virtual care while adhering to ethical standards.\n\n3. **[Availability and Coverage](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Availability-and-Coverage)** - Outlines expectations related to ensuring patient accessibility and continuity of care during virtual consultations.\n\n### Current Guidance\n- **Mandatory Expectations**: \n  - Providers must ensure that virtual care is safe, secure, and appropriate for the patient''s needs.\n  - While delivering virtual care, practitioners must maintain communication, continuity, and clarity, aligning with existing standards for face-to-face consultations.\n  - Protect patient privacy and confidentiality when providing care remotely.\n\n### Implementation Notes\n- Ensure that the technology used for virtual care is compliant with privacy regulations and does not compromise patient confidentiality.\n- Maintain thorough documentation of virtual appointments, just as you would for in-person visits.\n- Be aware of restrictions on prescribing medications through virtual consultations and maintain a clear consultation framework.\n\n### Related Resources\n- **[Advice to the Profession: Continuity of Care](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Continuity-of-Care/Advice-to-the-Profession-Continuity-of-Care)** - Focuses on maintaining consistent care, even in transitions to virtual platforms.\n- **[Protecting Personal Health Information](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Protecting-Personal-Health-Information/Advice-to-the-Profession-Protecting-Personal-Healt)** - Addresses confidentiality issues in virtual environments.\n\n### Currency Note\nThe guidelines were confirmed as current, with a high level of confidence (approximately 91% certainty). For the most up-to-date policies, always consult the official CPSO website. \n\nFeel free to ask if you need further information on a specific aspect of virtual care!", "type": "function_call_output"}','2025-09-28 17:21:02');
INSERT INTO agent_messages VALUES(23,'test_langfuse_session','{"call_id": "call_tOMhO7FUdHLixUQbPQQDJBQK", "output": "In Ontario, billing codes for virtual care include the following:\n\n1. **K300 - Virtual Care Services**\n   - Description: Modality Indicator For Video Technology Used During The Service.\n   - Related Codes:\n     - K300A (Modality Indicator For Video Technology Used During The Service)\n     - Other indicator for telephone technology.\n\n2. **A101 - Limited Virtual Care by Video**\n   - Fee Amount: **$20.00**\n   - Medical Specialty: General Surgery (Category 03)\n   - Related Reference Code: A102\n\n### Additional Information\n- For more details, referral, and guidelines on virtual care billing codes, you can refer to the [OHIP Schedule of Benefits (March 2025)](https://www.ontario.ca/files/2025-03/moh-schedule-benefit-2024-03-04.pdf).\n\nIf you need further information or additional codes, feel free to ask!", "type": "function_call_output"}','2025-09-28 17:21:02');
INSERT INTO agent_messages VALUES(24,'test_langfuse_session','{"id": "msg_68d96e7eefd48190a4d1324ed24cf43e05ba4b77ac14e6cc", "content": [{"annotations": [], "text": "### Summary of CPSO Guidelines and Billing Codes for Virtual Care in Ontario\n\n#### CPSO Guidelines for Virtual Care\n\n- **Mandatory Expectations**:\n  - Ensure virtual care is safe, secure, and suitable for the patient''s needs.\n  - Maintain the same standards of communication and continuity as face-to-face consultations.\n  - Protect patient privacy and confidentiality during virtual interactions.\n\n- **Implementation Details**:\n  - Use technology compliant with privacy regulations.\n  - Thoroughly document virtual consultations similar to in-person visits.\n  - Be mindful of restrictions related to prescribing medications through virtual means.\n\n- **Guidance Resources**:\n  - [Virtual Care Policy](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Virtual-Care)\n  - [Advice to the Profession on Continuity of Care](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Continuity-of-Care/Advice-to-the-Profession-Continuity-of-Care)\n\n#### Billing Codes for Virtual Care in Ontario\n\n- **K300 - Virtual Care Services**:\n  - Modality Indicator For Video: K300A\n  - Additional indicator for telephone use.\n\n- **A101 - Limited Virtual Care by Video**:\n  - Fee Amount: $20.00\n  - Specialty: General Surgery\n\n- **Reference**: For more detailed billing information, see the [OHIP Schedule of Benefits (March 2025)](https://www.ontario.ca/files/2025-03/moh-schedule-benefit-2024-03-04.pdf).\n\n### Practical Next Steps\n- Ensure compliance with CPSO guidelines when engaging in virtual care, focusing on privacy and documentation.\n- Utilize the appropriate billing codes for virtual care services to ensure proper compensation.\n\n### Medical Disclaimers\n- This information is intended for educational purposes only and should not replace specific medical or legal advice.\n- Always consult with relevant authorities or specialists for complex cases or when clarification about guidelines is needed.\n\nIf further assistance or clarification is needed on any specific aspects of virtual care, feel free to ask!", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-28 17:21:08');
