INSERT INTO agent_messages VALUES(30,'test_langfuse_session','{"id": "msg_68d96f49ea7c81909c9eb839cc9a67f705ba4b77ac14e6cc", "content": [{"annotations": [], "text": "### CPSO Guidelines for Virtual Care\n\n#### Key Expectations\n- **Safety and Suitability**: Ensure that virtual care is appropriate for the patient''s needs and conducted safely.\n- **Standards of Care**: Maintain communication, continuity, and clarity consistent with face-to-face consultations.\n- **Privacy and Confidentiality**: Protect patient information by using compliant technology.\n\n#### Resources\n- **[Virtual Care Policy](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Virtual-Care)**\n- **[Advice on Continuity of Care](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Continuity-of-Care/Advice-to-the-Profession-Continuity-of-Care)**\n\n### Billing Codes for Virtual Care in Ontario\n\n#### Relevant Codes\n- **K300**: Modality Indicator for Video Technology\n  - K300A for Video technology\n  - Telephone technology indicators available\n\n- **A101**: Limited Virtual Care by Video\n  - **Fee**: $20.00\n  - Applies to General Surgery\n\n#### Reference\n- See the [OHIP Schedule of Benefits (March 2025)](https://www.ontario.ca/files/2025-03/moh-schedule-benefit-2024-03-04.pdf) for more detailed information.\n\n### Next Steps\n- Follow CPSO guidelines to ensure compliant and effective virtual care.\n- Use the correct billing codes to align with OHIP standards.\n\n### Disclaimers\n- This guidance is for educational purposes only and does not replace professional advice.\n- Consult with relevant authorities or specialists for specific questions or complex situations.\n\nFeel free to ask if you need more information!", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-28 17:24:30');
