INSERT INTO agent_messages VALUES(45,'test_langfuse_stream','{"call_id": "call_29hoTP0MuOHCZVLv7C6T2l0D", "output": "The Ontario Drug Benefit (ODB) formulary covers several diabetes medications. Here are a few key examples:\n\n### Covered Medications:\n1. **Tresiba (Insulin Degludec)**\n   - **DINs**:\n     - [02467887](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467887): 200U/mL Inj Sol-Flextouch Pref Pen 3x3mL Pk\n     - [02467860](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467860): 100U/mL Inj Sol-3X5mL Cart Pk\n     - [02467879](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467879): 100U/mL Inj Sol-Flextouch Pref Pen 5x3mL Pk\n\n### Not Covered Medications:\n- **Diabeta (Glyburide)**:\n   - **DINs**:\n     - 02224569 (5mg Tab) - Not covered\n     - 02224550 (2.5mg Tab) - Not covered\n\n### Additional Information:\n- **General Benefit**: Tresiba is covered under the general benefit for patients eligible for the ODB.\n- **Not a Benefit**: Diabeta (Glyburide) is not covered under ODB.\n\nFor more comprehensive information, including other insulin types and oral anti-diabetic agents, you may check directly on the [Ontario Drug Benefit Formulary](https://www.formulary.health.gov.on.ca/).\n\nPlease consult the official formulary for any updates or changes to coverage.", "type": "function_call_output"}','2025-09-28 17:31:11');
INSERT INTO agent_messages VALUES(46,'test_langfuse_stream','{"id": "msg_68d970e056388196ab6edcbd1d54da9208abbc755caebbb9", "content": [{"annotations": [], "text": "### ODB Coverage for Diabetes Medications\n\n#### Covered Medications\n1. **Tresiba (Insulin Degludec)**\n   - **Forms Available**:\n     - **DIN 02467887**: 200U/mL (Flextouch Pref Pen - 3x3mL)\n     - **DIN 02467860**: 100U/mL (3x5mL Cartridges)\n     - **DIN 02467879**: 100U/mL (Flextouch Pref Pen - 5x3mL)\n   - **Coverage**: General Benefit\n   - [More on Tresiba](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467887)\n\n#### Not Covered Medications\n- **Diabeta (Glyburide)**\n  - **DINs**:\n    - 02224569: 5mg Tablets\n    - 02224550: 2.5mg Tablets\n  - **Coverage**: Not a Benefit\n  - [More on Diabeta](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02224569)\n\n### Key Points\n- **Tresiba is covered** under ODB as a general benefit.\n- **Glyburide (Diabeta)** is not included in the ODB formulary.\n\n### Next Steps\n- **Verify Coverage**: Always confirm with the ODB formulary for the latest coverage details.\n- **Consult with Healthcare Providers**: Explore alternative options if needed.\n\n### Disclaimer\nThis information is educational and should not replace professional medical advice. Always consult healthcare professionals for medical decisions. If further information is needed, feel free to reach out!", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-28 17:31:15');
INSERT INTO agent_messages VALUES(47,'test_langfuse_session','{"content": "What are the CPSO guidelines for virtual care and what billing codes apply?", "role": "user"}','2025-09-28 17:34:15');
INSERT INTO agent_messages VALUES(48,'test_langfuse_session','{"id": "msg_68d97198c9b88190916533a18582e2b905ba4b77ac14e6cc", "content": [{"annotations": [], "text": "### CPSO Guidelines for Virtual Care\n\n#### Key Expectations\n- **Safety and Suitability**: Ensure that virtual care is appropriate for the patient''s condition and conducted safely.\n- **Standards of Care**: Maintain consistent communication, continuity, and clarity, akin to in-person consultations.\n- **Privacy and Confidentiality**: Use technology that safeguards patient information and complies with privacy laws.\n\n#### Resources\n- **[Virtual Care Policy](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Virtual-Care)**\n- **[Continuity of Care Guidance](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Continuity-of-Care/Advice-to-the-Profession-Continuity-of-Care)**\n\n### Billing Codes for Virtual Care in Ontario\n\n#### Relevant Codes\n- **K300**: Modality Indicator for Video Technology\n  - **K300A**: Specifically for video use\n  - Other indicators available for telephone\n\n- **A101**: Limited Virtual Care by Video\n  - **Fee**: $20.00\n  - Applicable to General Surgery\n\n#### Reference\n- For detailed billing guidance, see the [OHIP Schedule of Benefits (March 2025)](https://www.ontario.ca/files/2025-03/moh-schedule-benefit-2024-03-04.pdf).\n\n### Next Steps\n- Adhere to CPSO guidelines for providing compliant and effective virtual care.\n- Use the correct billing codes in alignment with OHIP requirements.\n\n### Disclaimers\n- This information is for educational purposes only and should not replace professional advice.\n- For specific or complex cases, consult with relevant authorities.\n\nFeel free to ask if you have more questions or need further clarification!", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-28 17:34:20');
INSERT INTO agent_messages VALUES(49,'test_langfuse_stream','{"content": "What diabetes medications are covered by ODB?", "role": "user"}','2025-09-28 17:34:25');
