INSERT INTO agent_messages VALUES(51,'test_langfuse_stream','{"call_id": "call_eLRILjJGUYAer02w4wWdn5J0", "output": "## Diabetes Medications Covered by ODB\n\n1. **Insulin Degludec (Tresiba)**:\n   - **DINs**: \n     - 02467887 - Tresiba 200U/mL (Inj Sol-Flextouch Pref Pen)\n     - 02467860 - Tresiba 100U/mL (Inj Sol-3X5mL Cart)\n     - 02467879 - Tresiba 100U/mL (Inj Sol-Flextouch Pref Pen)\n   - **Coverage**: General Benefit\n   \n   - **Links to Formulary**:\n     - [DIN: 02467887 - Tresiba](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467887)\n     - [DIN: 02467860 - Tresiba](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467860)\n     - [DIN: 02467879 - Tresiba](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467879)\n\n2. **Glyburide (Diabeta)** (Note: Not a Benefit):\n   - **DINs**: \n     - 02224569 - Diabeta 5mg Tab\n     - 02224550 - Diabeta 2.5mg Tab\n   - **Coverage**: Not covered under ODB.\n\n   - **Links to Formulary**:\n     - [DIN: 02224569 - Diabeta](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02224569)\n     - [DIN: 02224550 - Diabeta](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02224550)\n\n### Summary\n- **Covered Medications**: Insulin Degludec (Tresiba)\n- **Not Covered Medications**: Glyburide (Diabeta)\n\nThis coverage information is subject to change, so please verify eligibility and current listings through the [Ontario Drug Benefit Formulary](https://www.formulary.health.gov.on.ca).", "type": "function_call_output"}','2025-09-28 17:34:42');
