INSERT INTO agent_messages VALUES(57,'test_langfuse_stream','{"call_id": "call_Urmf0jvOHF5vBu5e8fMHG3pT", "output": "Here are some diabetes medications covered by the Ontario Drug Benefit (ODB):\n\n### Covered Medications:\n1. **Tresiba (Insulin Degludec)**\n   - **DIN:** 02467887\n     - **Strength:** 200U/mL, Flextouch Pref Pen (3x3mL Pack)\n     - **Price:** $137.01 per unit\n     - **Coverage Type:** General Benefit\n     - [More Information](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467887)\n   - **DIN:** 02467860\n     - **Strength:** 100U/mL, (3x5mL Cart Pack)\n     - **Price:** $114.17 per unit\n     - **Coverage Type:** General Benefit\n     - [More Information](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467860)\n   - **DIN:** 02467879\n     - **Strength:** 100U/mL, Flextouch Pref Pen (5x3mL Pack)\n     - **Price:** $114.17 per unit\n     - **Coverage Type:** General Benefit\n     - [More Information](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467879)\n\n### Not Covered:\n- **Diabeta (Glyburide)**\n   - Both strengths (5mg and 2.5mg) are not covered by ODB. \n\n### Additional Information:\nFor further details on eligibility and to review the complete list of medications, please consult the [Ontario Drug Benefit Formulary](https://www.formulary.health.gov.on.ca/). \n\n### Next Steps:\nTo prescribe any of the covered medications, ensure that the patient meets any additional clinical criteria if required. Always check for the most current coverage as it can change.", "type": "function_call_output"}','2025-09-28 17:40:26');
