INSERT INTO agent_messages VALUES(69,'test_langfuse_stream','{"call_id": "call_KoP6tENQIDUZp7LHVLBOsWkl", "output": "Here are some diabetes medications that are covered by the Ontario Drug Benefit (ODB) program:\n\n### Covered Medications\n\n1. **Tresiba (Insulin Degludec)**\n   - **DIN:** 02467860\n     - **Formulation:** 100U/mL Inj Sol-3X5mL Cart Pk\n     - **Price:** $114.17 per unit\n     - **Coverage:** General Benefit\n     - [More Info](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467860)\n\n   - **DIN:** 02467887\n     - **Formulation:** 200U/mL Inj Sol-Flextouch Pref Pen 3x3mL Pk\n     - **Price:** $137.01 per unit\n     - **Coverage:** General Benefit\n     - [More Info](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467887)\n\n   - **DIN:** 02467879\n     - **Formulation:** 100U/mL Inj Sol-Flextouch Pref Pen 5x3mL Pk\n     - **Price:** $114.17 per unit\n     - **Coverage:** General Benefit\n     - [More Info](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467879)\n\n### Non-Covered Medications\n\n1. **Diabeta (Glyburide)**\n   - **DIN:** 02224569\n     - **Formulation:** 5mg Tab\n     - **Coverage:** Not a Benefit\n     - [More Info](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02224569)\n\n   - **DIN:** 02224550\n     - **Formulation:** 2.5mg Tab\n     - **Coverage:** Not a Benefit\n     - [More Info](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02224550)\n\n### Summary\n- **Insulin Degludec (Tresiba)** is covered under the ODB program as a general benefit.\n- **Glyburide (Diabeta)** is not covered under the ODB.\n\nFor additional insights about the specific requirements or to check for any updates, you may want to refer to the [official ODB formulary site](https://www.formulary.health.gov.on.ca).", "type": "function_call_output"}','2025-09-28 17:53:35');
INSERT INTO agent_messages VALUES(70,'test_langfuse_stream','{"id": "msg_68d9762032248196bf6272e3ceeaff4c08abbc755caebbb9", "content": [{"annotations": [], "text": "### ODB Coverage for Diabetes Medications\n\n#### Covered Medications\n1. **Tresiba (Insulin Degludec)**\n   - **Available Forms**:\n     - **100U/mL Cartridges** (DIN: 02467860)\n       - **Price**: $114.17\n       - **Coverage**: General Benefit\n       - [More Info](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467860)\n     - **200U/mL Flextouch Pen** (DIN: 02467887)\n       - **Price**: $137.01\n       - **Coverage**: General Benefit\n       - [More Info](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467887)\n     - **100U/mL Flextouch Pen** (DIN: 02467879)\n       - **Price**: $114.17\n       - **Coverage**: General Benefit\n       - [More Info](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02467879)\n\n#### Not Covered Medications\n- **Diabeta (Glyburide)**\n  - **DINs**:\n    - 5mg Tablets (DIN: 02224569)\n    - 2.5mg Tablets (DIN: 02224550)\n  - **Coverage**: Not a Benefit\n  - [More Info](https://www.formulary.health.gov.on.ca/formulary/results.xhtml?q=02224569)\n\n### Key Points\n- **Tresiba** is available under general benefits, making it accessible for patients requiring long-acting insulin.\n- **Glyburide (Diabeta)** is not covered under the ODB.\n\n### Recommendations\n- **Review Formulary**: Always check the [Ontario Drug Benefit Formulary](https://www.formulary.health.gov.on.ca) for the latest coverage.\n- **Consult Health Professionals**: Discuss with healthcare providers for alternative medications if necessary.\n\n### Disclaimer\nThis information is provided for educational purposes and should be confirmed with a healthcare provider. Always verify with official resources for clinical decisions. If additional information is needed, feel free to ask!", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-28 17:53:39');
INSERT INTO agent_messages VALUES(71,'test_langfuse_session','{"content": "What are the CPSO guidelines for virtual care and what billing codes apply?", "role": "user"}','2025-09-28 18:00:45');
INSERT INTO agent_messages VALUES(72,'test_langfuse_session','{"id": "msg_68d977cee8a0819082cbcc2cef64e86605ba4b77ac14e6cc", "content": [{"annotations": [], "text": "### CPSO Guidelines for Virtual Care\n\n#### Key Expectations\n- **Safety and Suitability**: Ensure virtual care is appropriate for the patient''s condition and conducted safely.\n- **Standards of Care**: Maintain consistent communication, continuity, and clarity, similar to in-person consultations.\n- **Privacy and Confidentiality**: Use technology that protects patient information and complies with privacy laws.\n\n#### Resources\n- **[Virtual Care Policy](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Virtual-Care)**\n- **[Continuity of Care Guidance](https://www.cpso.on.ca/en/Physicians/Policies-Guidance/Policies/Continuity-of-Care/Advice-to-the-Profession-Continuity-of-Care)**\n\n### Billing Codes for Virtual Care in Ontario\n\n#### Relevant Codes\n- **K300**: Modality Indicator for Video Technology\n  - **K300A**: Specifically for video use\n  - Other indicators available for telephone\n\n- **A101**: Limited Virtual Care by Video\n  - **Fee**: $20.00\n  - Applies to General Surgery\n\n#### Reference\n- For detailed billing guidance, see the [OHIP Schedule of Benefits (March 2025)](https://www.ontario.ca/files/2025-03/moh-schedule-benefit-2024-03-04.pdf).\n\n### Next Steps\n- Adhere to CPSO guidelines for providing compliant and effective virtual care.\n- Use the appropriate billing codes in alignment with OHIP requirements.\n\n### Disclaimers\n- This is for educational purposes and not a substitute for legal or professional advice.\n- Consult relevant authorities for specific or complex situations.\n\nIf more information is needed, feel free to ask!", "type": "output_text", "logprobs": []}], "role": "assistant", "status": "completed", "type": "message"}','2025-09-28 18:00:50');
